Here is the commit message:
net: ethernet: mlx4: Avoid assigning a value to ring_cons but
 not used it anymore in mlx4_en_xmit()

We found a set but not used variable 'ring_cons' in mlx4_en_xmit(), it will
cause a warning when build the kernel. And after checking the commit record
of this function, we found that it was introduced by a previous patch.

So, We delete this redundant assignment code.

Fixes: 488a9b48e398 ("net/mlx4_en: Wake TX queues only when there's enough room")

Signed-off-by: Luo Jiaxing <luojiaxing@huawei.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The root cause of the bug was the introduction of an unused variable `ring_cons` in the `mlx4_en_xmit` function, which was assigned a value but never utilized in any subsequent operations. This redundancy led to a compiler warning during the kernel build process, indicating that the variable was unnecessary and could be removed to clean up the code.

Here is the patch:

 netdev_tx_t mlx4_en_xmit(struct sk_buff *skb, struct net_device *dev)
 {
 	struct skb_shared_info *shinfo = skb_shinfo(skb);
 	struct mlx4_en_priv *priv = netdev_priv(dev);
 	union mlx4_wqe_qpn_vlan	qpn_vlan = {};
 	struct mlx4_en_tx_ring *ring;
 	struct mlx4_en_tx_desc *tx_desc;
 	struct mlx4_wqe_data_seg *data;
 	struct mlx4_en_tx_info *tx_info;
 	int tx_ind;
 	int nr_txbb;
 	int desc_size;
 	int real_size;
 	u32 index, bf_index;
 	__be32 op_own;
 	int lso_header_size;
 	void *fragptr = NULL;
 	bool bounce = false;
 	bool send_doorbell;
 	bool stop_queue;
 	bool inline_ok;
 	u8 data_offset;
 	u32 ring_cons;
 	bool bf_ok;

 	tx_ind = skb_get_queue_mapping(skb);
 	ring = priv->tx_ring[TX][tx_ind];

 	if (unlikely(!priv->port_up))
 		goto tx_drop;

 	/* fetch ring->cons far ahead before needing it to avoid stall */
 	ring_cons = READ_ONCE(ring->cons);

 	real_size = get_real_size(skb, shinfo, dev, &lso_header_size,
 				  &inline_ok, &fragptr);
 	if (unlikely(!real_size))
 		goto tx_drop_count;

 	/* Align descriptor to TXBB size */
 	desc_size = ALIGN(real_size, TXBB_SIZE);
 	nr_txbb = desc_size >> LOG_TXBB_SIZE;
 	if (unlikely(nr_txbb > MAX_DESC_TXBBS)) {
 		if (netif_msg_tx_err(priv))
 			en_warn(priv, "Oversized header or SG list\n");
 		goto tx_drop_count;
 	}

 	bf_ok = ring->bf_enabled;
 	if (skb_vlan_tag_present(skb)) {
 		u16 vlan_proto;

 		qpn_vlan.vlan_tag = cpu_to_be16(skb_vlan_tag_get(skb));
 		vlan_proto = be16_to_cpu(skb->vlan_proto);
 		if (vlan_proto == ETH_P_8021AD)
 			qpn_vlan.ins_vlan = MLX4_WQE_CTRL_INS_SVLAN;
 		else if (vlan_proto == ETH_P_8021Q)
 			qpn_vlan.ins_vlan = MLX4_WQE_CTRL_INS_CVLAN;
 		else
 			qpn_vlan.ins_vlan = 0;
 		bf_ok = false;
 	}

 	netdev_txq_bql_enqueue_prefetchw(ring->tx_queue);

 	/* Track current inflight packets for performance analysis */
 	AVG_PERF_COUNTER(priv->pstats.inflight_avg,
 			 (u32)(ring->prod - ring_cons - 1));

 	/* Packet is good - grab an index and transmit it */
 	index = ring->prod & ring->size_mask;
 	bf_index = ring->prod;

 	/* See if we have enough space for whole descriptor TXBB for setting
 	 * SW ownership on next descriptor; if not, use a bounce buffer. */
 	if (likely(index + nr_txbb <= ring->size))
 		tx_desc = ring->buf + (index << LOG_TXBB_SIZE);
 	else {
 		tx_desc = (struct mlx4_en_tx_desc *) ring->bounce_buf;
 		bounce = true;
 		bf_ok = false;
 	}

 	/* Save skb in tx_info ring */
 	tx_info = &ring->tx_info[index];
 	tx_info->skb = skb;
 	tx_info->nr_txbb = nr_txbb;

 	if (!lso_header_size) {
 		data = &tx_desc->data;
 		data_offset = offsetof(struct mlx4_en_tx_desc, data);
 	} else {
 		int lso_align = ALIGN(lso_header_size + 4, DS_SIZE);

 		data = (void *)&tx_desc->lso + lso_align;
 		data_offset = offsetof(struct mlx4_en_tx_desc, lso) + lso_align;
 	}

 	/* valid only for none inline segments */
 	tx_info->data_offset = data_offset;

 	tx_info->inl = inline_ok;

 	tx_info->linear = lso_header_size < skb_headlen(skb) && !inline_ok;

 	tx_info->nr_maps = shinfo->nr_frags + tx_info->linear;
 	data += tx_info->nr_maps - 1;

 	if (!tx_info->inl)
 		if (!mlx4_en_build_dma_wqe(priv, shinfo, data, skb,
 					   lso_header_size, ring->mr_key,
 					   tx_info))
 			goto tx_drop_count;

 	/*
 	 * For timestamping add flag to skb_shinfo and
 	 * set flag for further reference
 	 */
 	tx_info->ts_requested = 0;
 	if (unlikely(ring->hwtstamp_tx_type == HWTSTAMP_TX_ON &&
 		     shinfo->tx_flags & SKBTX_HW_TSTAMP)) {
 		shinfo->tx_flags |= SKBTX_IN_PROGRESS;
 		tx_info->ts_requested = 1;
 	}

 	/* Prepare ctrl segement apart opcode+ownership, which depends on
 	 * whether LSO is used */
 	tx_desc->ctrl.srcrb_flags = priv->ctrl_flags;
 	if (likely(skb->ip_summed == CHECKSUM_PARTIAL)) {
 		if (!skb->encapsulation)
 			tx_desc->ctrl.srcrb_flags |= cpu_to_be32(MLX4_WQE_CTRL_IP_CSUM |
 								 MLX4_WQE_CTRL_TCP_UDP_CSUM);
 		else
 			tx_desc->ctrl.srcrb_flags |= cpu_to_be32(MLX4_WQE_CTRL_IP_CSUM);
 		ring->tx_csum++;
 	}

 	if (priv->flags & MLX4_EN_FLAG_ENABLE_HW_LOOPBACK) {
 		struct ethhdr *ethh;

 		/* Copy dst mac address to wqe. This allows loopback in eSwitch,
 		 * so that VFs and PF can communicate with each other
 		 */
 		ethh = (struct ethhdr *)skb->data;
 		tx_desc->ctrl.srcrb_flags16[0] = get_unaligned((__be16 *)ethh->h_dest);
 		tx_desc->ctrl.imm = get_unaligned((__be32 *)(ethh->h_dest + 2));
 	}

 	/* Handle LSO (TSO) packets */
 	if (lso_header_size) {
 		int i;

 		/* Mark opcode as LSO */
 		op_own = cpu_to_be32(MLX4_OPCODE_LSO | (1 << 6)) |
 			((ring->prod & ring->size) ?
 				cpu_to_be32(MLX4_EN_BIT_DESC_OWN) : 0);

 		/* Fill in the LSO prefix */
 		tx_desc->lso.mss_hdr_size = cpu_to_be32(
 			shinfo->gso_size << 16 | lso_header_size);

 		/* Copy headers;
 		 * note that we already verified that it is linear */
 		memcpy(tx_desc->lso.header, skb->data, lso_header_size);

 		ring->tso_packets++;

 		i = shinfo->gso_segs;
 		tx_info->nr_bytes = skb->len + (i - 1) * lso_header_size;
 		ring->packets += i;
 	} else {
 		/* Normal (Non LSO) packet */
 		op_own = cpu_to_be32(MLX4_OPCODE_SEND) |
 			((ring->prod & ring->size) ?
 			 cpu_to_be32(MLX4_EN_BIT_DESC_OWN) : 0);
 		tx_info->nr_bytes = max_t(unsigned int, skb->len, ETH_ZLEN);
 		ring->packets++;
 	}
 	ring->bytes += tx_info->nr_bytes;
 	AVG_PERF_COUNTER(priv->pstats.tx_pktsz_avg, skb->len);

 	if (tx_info->inl)
 		build_inline_wqe(tx_desc, skb, shinfo, fragptr);

 	if (skb->encapsulation) {
 		union {
 			struct iphdr *v4;
 			struct ipv6hdr *v6;
 			unsigned char *hdr;
 		} ip;
 		u8 proto;

 		ip.hdr = skb_inner_network_header(skb);
 		proto = (ip.v4->version == 4) ? ip.v4->protocol :
 						ip.v6->nexthdr;

 		if (proto == IPPROTO_TCP || proto == IPPROTO_UDP)
 			op_own |= cpu_to_be32(MLX4_WQE_CTRL_IIP | MLX4_WQE_CTRL_ILP);
 		else
 			op_own |= cpu_to_be32(MLX4_WQE_CTRL_IIP);
 	}

 	ring->prod += nr_txbb;

 	/* If we used a bounce buffer then copy descriptor back into place */
 	if (unlikely(bounce))
 		tx_desc = mlx4_en_bounce_to_desc(priv, ring, index, desc_size);

 	skb_tx_timestamp(skb);

 	/* Check available TXBBs And 2K spare for prefetch */
 	stop_queue = mlx4_en_is_tx_ring_full(ring);
 	if (unlikely(stop_queue)) {
 		netif_tx_stop_queue(ring->tx_queue);
 		ring->queue_stopped++;
 	}

 	send_doorbell = __netdev_tx_sent_queue(ring->tx_queue,
 					       tx_info->nr_bytes,
 					       netdev_xmit_more());

 	real_size = (real_size / 16) & 0x3f;

 	bf_ok &= desc_size <= MAX_BF && send_doorbell;

 	if (bf_ok)
 		qpn_vlan.bf_qpn = ring->doorbell_qpn | cpu_to_be32(real_size);
 	else
 		qpn_vlan.fence_size = real_size;

 	mlx4_en_tx_write_desc(ring, tx_desc, qpn_vlan, desc_size, bf_index,
 			      op_own, bf_ok, send_doorbell);

 	if (unlikely(stop_queue)) {
 		/* If queue was emptied after the if (stop_queue) , and before
 		 * the netif_tx_stop_queue() - need to wake the queue,
 		 * or else it will remain stopped forever.
 		 * Need a memory barrier to make sure ring->cons was not
 		 * updated before queue was stopped.
 		 */
 		smp_rmb();

-		ring_cons = READ_ONCE(ring->cons);
 		if (unlikely(!mlx4_en_is_tx_ring_full(ring))) {
 			netif_tx_wake_queue(ring->tx_queue);
 			ring->wake_queue++;
 		}
 	}
 	return NETDEV_TX_OK;

 tx_drop_count:
 	ring->tx_dropped++;
 tx_drop:
 	dev_kfree_skb_any(skb);
 	return NETDEV_TX_OK;
 }



